document.getElementById('legacyExport').addEventListener('click',()=>{try{let data=localStorage.getItem('bloom-v1');if(!data){document.getElementById('status').textContent='No earlier records found in this browser and address.';return}JSON.parse(data);let url=URL.createObjectURL(new Blob([data],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='bloom-earlier-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent='Export downloaded. The earlier browser copy remains untouched.'}catch{document.getElementById('status').textContent='Could not read earlier records.'}});
